DO $$
DECLARE
  rec RECORD;
BEGIN
  FOR rec IN SELECT request_id FROM refund_requests ORDER BY request_id LOOP
    UPDATE refund_requests
    SET final_price = original_price - discount_applied
    WHERE request_id = rec.request_id;

    UPDATE refund_requests
    SET refund_amount = CASE
      WHEN refund_status = 'approved' AND final_price > 100 THEN final_price * 0.90
      WHEN refund_status = 'approved' THEN final_price
      ELSE 0
    END
    WHERE request_id = rec.request_id;
  END LOOP;
END $$;

SELECT * FROM refund_requests ORDER BY request_id;
